impl CapabilityClient for UsageBillingClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            close_period: dependencies.one::<UsageBillingClosePeriod>()?,
            get_account: dependencies.one::<UsageBillingGetAccount>()?,
            get_period: dependencies.one::<UsageBillingGetPeriod>()?,
            inspect_delivery: dependencies.one::<UsageBillingInspectDelivery>()?,
            list_accounts: dependencies.one::<UsageBillingListAccounts>()?,
            list_periods: dependencies.one::<UsageBillingListPeriods>()?,
            put_account: dependencies.one::<UsageBillingPutAccount>()?,
            reconcile_next: dependencies.one::<UsageBillingReconcileNext>()?,
            resolve_delivery: dependencies.one::<UsageBillingResolveDelivery>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for UsageBillingClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    close_period: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingClosePeriod>()?,
                    get_account: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingGetAccount>()?,
                    get_period: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingGetPeriod>()?,
                    inspect_delivery: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingInspectDelivery>()?,
                    list_accounts: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingListAccounts>()?,
                    list_periods: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingListPeriods>()?,
                    put_account: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingPutAccount>()?,
                    reconcile_next: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingReconcileNext>()?,
                    resolve_delivery: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<UsageBillingResolveDelivery>()?,
                    },
                ))
            })
            .collect()
    }
}

